-- Baseline schema for kcr-backend (state of 2026-10-25).
-- Replaces the schema previously generated by ddl-auto=update plus manual fixes.
-- Applied by Flyway to an empty database. Never edit this file after it has been
-- applied to any database -- any schema change goes into a new V<n>__<name>.sql.

CREATE TABLE users (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username    VARCHAR(255) NOT NULL,
    password    VARCHAR(255) NOT NULL,
    email       VARCHAR(255),
    role        VARCHAR(255) NOT NULL,
    CONSTRAINT uk_users_username UNIQUE (username),
    CONSTRAINT uk_users_email    UNIQUE (email),
    CONSTRAINT users_role_check  CHECK (role IN ('ADMIN', 'OPERATOR'))
);

CREATE TABLE refresh_tokens (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    token_hash  VARCHAR(255) NOT NULL,
    user_id     BIGINT NOT NULL,
    expiry_date TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    CONSTRAINT uk_refresh_tokens_token_hash UNIQUE (token_hash),
    CONSTRAINT fk_refresh_tokens_users FOREIGN KEY (user_id) REFERENCES users (id)
);
